import assert from 'node:assert/strict';import crypto from 'node:crypto';import fs from 'node:fs';import {loadPlayerCatalogue,loadRepositoryModule as load} from './load-player-catalogue.mjs';
const cards=JSON.parse(fs.readFileSync('assets/data/totw7Cards20261028.json'));const all=loadPlayerCatalogue(),ids=new Set(cards.map(c=>c.id));assert.equal(cards.length,23);assert.equal(ids.size,23);assert.equal(all.length,20223);assert.equal(new Set(all.map(c=>c.id)).size,20223);const before=all.filter(c=>!ids.has(c.id));assert.equal(before.length,20200);assert.equal(crypto.createHash('sha256').update(JSON.stringify(before)).digest('hex'),'baca650862b0581c0f463054c3fc4632c4f3a1342300e8e15aea37c76cb68d18');const original=before.filter(c=>!['recent-50545314','recent-50590296'].includes(c.id));assert.equal(crypto.createHash('sha256').update(JSON.stringify(original)).digest('hex'),'27e3cc3dcb38484049468bf481fbba6c222cba3c8b478b506561dbf0870e6d36');const {recentCardFor,recentCardMeta}=load('lib/recentCards.ts');const {RECENT_CARD_ART}=load('lib/recentCardArt.ts');const {META_ATTRS}=load('lib/playerMeta.ts');const {playerEditionsFor}=load('lib/playerEditions.ts');const {playerMatches,EMPTY_FILTERS}=load('lib/playerFilter.ts');for(const c of cards){assert.deepEqual(recentCardFor(c.id),c);assert.equal(c.id,`recent-${c.itemId}`);assert(c.sourceUrl.includes(`27-${c.itemId}/`));assert(c.referenceUrl.startsWith('https://www.futbin.com/27/player/'));assert(c.artUrl.includes(`27-${c.itemId}.`));assert.equal(Object.keys(c.attributes).length,34);for(const key of META_ATTRS)assert.equal(typeof recentCardMeta(c).stats[key],'number',`${c.id} ${key}`);assert(c.price.kind==='market');for(const v of [c.price.console,c.price.pc])assert(v===null||v>0);assert(playerEditionsFor(c).some(x=>x.id===c.baseId));assert(playerMatches(c,{...EMPTY_FILTERS,kind:'totw'}));const art=fs.readFileSync(RECENT_CARD_ART[c.id]);assert.equal(art.subarray(0,8).toString('hex'),'89504e470d0a1a0a');assert.equal(art.readUInt32BE(16),300);assert.equal(art.readUInt32BE(20),419);}assert.equal(cards.find(c=>c.itemId===67351699).club,'רומא');assert.equal(cards.find(c=>c.itemId===67368061).club,'אסטון וילה');assert.equal(cards.find(c=>c.itemId===67192374).club,'Molde FK');console.log('PASS: 23 exact TOTW 7 cards, art, positions, attributes, filters, market quotes and editions; all 20,200 earlier cards preserved.');
